struct Heap{v:Vec<i64>,max:bool}
impl Heap{fn new(max:bool)->Self{Self{v:Vec::new(),max}}fn better(&self,a:i64,b:i64)->bool{if self.max{a>b}else{a<b}}fn push(&mut self,x:i64){self.v.push(x);let mut i=self.v.len()-1;while i>0{let p=(i-1)/2;if !self.better(self.v[i],self.v[p]){break}self.v.swap(i,p);i=p}}fn pop(&mut self)->i64{let x=self.v[0];let last=self.v.pop().unwrap();if !self.v.is_empty(){self.v[0]=last;let mut i=0;loop{let l=2*i+1;let r=l+1;let mut b=i;if l<self.v.len()&&self.better(self.v[l],self.v[b]){b=l}if r<self.v.len()&&self.better(self.v[r],self.v[b]){b=r}if b==i{break}self.v.swap(i,b);i=b}}x}}
#[no_mangle]
pub unsafe extern "C" fn median_of_running_array_integer(input:*const i64,length:usize,output:*mut u8,capacity:usize)->i64{if input.is_null()||length<2{return -1}let v=std::slice::from_raw_parts(input,length);if !(1..=256).contains(&v[0])||length!=v[0] as usize+1||v[1..].iter().any(|x|!(-1_000_000..=1_000_000).contains(x)){return -1}let n=v[0] as usize;if output.is_null()||capacity<n*8{return -2}let mut lo=Heap::new(true);let mut hi=Heap::new(false);let out=std::slice::from_raw_parts_mut(output,n*8);for(i,&x)in v[1..].iter().enumerate(){if !hi.v.is_empty()&&x<hi.v[0]{lo.push(x)}else{hi.push(x)}if lo.v.len()>hi.v.len()+1{hi.push(lo.pop())}else if hi.v.len()>lo.v.len()+1{lo.push(hi.pop())}let m=if lo.v.len()==hi.v.len(){(lo.v[0]+hi.v[0])/2}else if lo.v.len()>hi.v.len(){lo.v[0]}else{hi.v[0]};out[i*8..i*8+8].copy_from_slice(&m.to_le_bytes());} (n*8) as i64}
